SELECT id, shop_name, area_id, shop_kind_id, is_closed
FROM shops
WHERE id = #{id}

SELECT id, shop_name, area_id, shop_kind_id, is_closed
FROM shops
WHERE shop_name = #{shopName} AND area_id = #{areaId}

mapper.update:
UPDATE shops
SET shop_name = #{shopName},
    area_id = #{areaId},
    shop_kind_id = #{shopKindId},
    is_closed = #{isClosed}
WHERE id = #{id}

mapper.select:
SELECT id, shop_name, area_id, shop_kind_id, is_closed FROM shops WHERE area_id = #{areaId} AND is_closed = FALSE
AND shop_name COLLATE utf8mb4_0900_ai_ci LIKE CONCAT('%', #{keyword}, '%')
ORDER BY shop_name LIMIT #{limit}
